#include <iostream>
#include <vector>
#include <string>
using namespace std;

long long total(const vector<long long>& a, size_t i, long long current) {
    if (i == a.size()) return current;
    return total(a, i + 1, current) + total(a, i + 1, current ^ a[i]);
}

int main() {
    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    cout << total(a, 0, 0) << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    static long total(long[] a, int i, long current) {
        if (i == a.length) return current;
        return total(a, i + 1, current) + total(a, i + 1, current ^ a[i]);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = sc.nextLong();

        System.out.println(total(a, 0, 0));
    }
}
